int get_sas_phy_event_counts(struct sas_phy *phy) {
    void *request = NULL;
    void *response = NULL;
    int result = -ENOMEM;

    if (!phy) {
        return -EINVAL;
    }

    request = kmalloc(REQUEST_SIZE, GFP_KERNEL);
    if (!request) {
        return -ENOMEM;
    }

    response = kmalloc(RESPONSE_SIZE, GFP_KERNEL);
    if (!response) {
        kfree(request);
        return -ENOMEM;
    }

    initialize_request(request, phy->number);

    result = execute_task(request, response);
    if (result < 0) {
        goto cleanup;
    }

    phy->frame_status = get_frame_status(response);
    phy->invalid_dword_count = get_invalid_dword_count(response);
    phy->running_disparity_error_count = get_running_disparity_error_count(response);
    phy->loss_of_dword_sync_count = get_loss_of_dword_sync_count(response);
    phy->phy_reset_count = get_phy_reset_count(response);
    phy->link_reset_count = get_link_reset_count(response);
    phy->recovery_count = get_recovery_count(response);
    phy->invalid = get_invalid(response);

    result = 0;

    cleanup:
    kfree(request);
    kfree(response);
    return result;
}
